oxy_webhelp_navlinks = {"account_unlocking-d39307e15464":{"topics":[{"title":"Unlocking user accounts administratively","shortdesc":"<p class=\"shortdesc\">As a user with administrator or <span class=\"ph\">RSC<\/span> account owner privileges, unlock         a local user account or an SSO user account locked due to administrative actions, brute         force, or user inactivity.<\/p>","href":"saas\/common\/unlocking_user_accounts_administratively.html","attributes":{"data-id":"unlocking_user_accounts_administratively"},"menu":{"hasChildren":false},"tocID":"unlocking_user_accounts_administratively-d39307e15475","topics":[]},{"title":"Configuring auto unlock for brute force lock","shortdesc":"<p class=\"shortdesc\">As an administrator, you can configure the automatic unlocking of user accounts that         have been locked due to brute force attempts.<\/p>","href":"saas\/common\/configuring_auto_unlock_brute_force_lock.html","attributes":{"data-id":"configuring_auto_unlock_brute_force_lock"},"menu":{"hasChildren":false},"tocID":"configuring_auto_unlock_brute_force_lock-d39307e15489","topics":[]},{"title":"Unlocking inactive accounts","shortdesc":"<p class=\"shortdesc\">Unlock user accounts locked due to inactivity using a self-service password reset         feature.<\/p>","href":"saas\/common\/unlocking_inactive_accounts.html","attributes":{"data-id":"unlocking_inactive_account"},"menu":{"hasChildren":false},"tocID":"unlocking_inactive_account-d39307e15500","topics":[]}]}};